window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-d1cb7a3fc7bbece2"]={"versions": [{"id": "FIG-d1cb7a3fc7bbece2", "releases": ["R2.1.20"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">PDU-Strukturdiagramm / Bit- und Byte-Layout der Protokoll-Dateneinheit für das FlexRay Transportprotokoll (AUTOSAR Classic Platform, BSW-Modul <code>FrTp</code>). Dargestellt ist das N-PDU-Format des First Frame Extended.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Format setzt sich zusammen aus PCI (Protocol Control Information, orange hinterlegt, Gesamtlänge 2 Byte) und Nutzdaten (Data, gelb hinterlegt, „Length depending on configuration“):</p>\n<ul class=\"fig-list\"><li><strong>FT (4 Bit)</strong>: Frame Type Identifier (First Frame Extended).\n</li><li><strong>LDL (4 Bit)</strong>: Low Data Length bzw. Teillängenfeld.\n</li><li><strong>DL (8 Bit)</strong>: Data Length zur Angabe der Gesamtlänge der Nachricht.\n</li><li><strong>Data</strong>: Nutzdatenfeld variabler Länge gemäß Konfiguration.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Beim Versand segmentierter Nachrichten leitet der First Frame Extended die Übertragung ein. Der Empfänger wertet zunächst den PCI-Header aus: Über FT wird der Rahmentyp identifiziert und aus LDL sowie DL die Gesamtnachrichtengröße ermittelt. Die folgenden Nutzdatenbytes füllen das PDU-Datenfeld auf.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Festlegung der Paketstruktur des First Frame Extended: Der FrTp-Treiber muss den 2-Byte-PCI mit den Feldern FT (4 Bit), LDL (4 Bit) und DL (8 Bit) kodieren bzw. dekodieren. Die PDU-Gesamtlänge und die verbleibende Nutzdatenlänge hängen von der jeweiligen FlexRay-PDU-Konfiguration ab.</p>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-4a8d65dfd41de856", "releases": ["R3.0.7", "R3.1.5"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">PDU-Strukturdiagramm / Bit- und Byte-Layout der Protokoll-Dateneinheit für das FlexRay Transportprotokoll (AUTOSAR Classic Platform, BSW-Modul <code>FrTp</code>). Dargestellt ist das N-PDU-Format des First Frame Extended.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Format setzt sich zusammen aus PCI (Protocol Control Information, orange hinterlegt, Gesamtlänge 5 Byte) und Nutzdaten (Data, gelb hinterlegt, „Length depending on configuration“):</p>\n<ul class=\"fig-list\"><li><strong>FT (4 Bit)</strong>: Frame Type Identifier (First Frame Extended).\n</li><li><strong>Res (4 Bit)</strong>: Reservierte Bits.\n</li><li><strong>DL (32 Bit)</strong>: 32-Bit-Datenlängenfeld für die Gesamtlänge der Nachricht.\n</li><li><strong>Data</strong>: Nutzdatenfeld variabler Länge gemäß Konfiguration.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Beim Versand segmentierter Nachrichten leitet der First Frame Extended die Übertragung ein. Der Empfänger wertet den 5-Byte-PCI-Header aus: Über FT wird der Rahmentyp identifiziert und aus dem 32-Bit-Feld DL die vollständige Nachrichtengröße entnommen; das 4-Bit-Feld Res bleibt ungenutzt bzw. reserviert. Die verbleibende PDU-Kapazität transportiert Nutzdaten.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Festlegung des First Frame Extended mit erweitertem Adress-/Längenbereich: Der PCI umfasst verbindlich 5 Byte, aufgeteilt in FT (4 Bit), Res (4 Bit) und DL (32 Bit). Durch die 32-Bit-Längenangabe können große Datensätze adressiert werden. Implementierungen müssen das Feld Res entsprechend den Spezifikationsvorgaben maskieren bzw. ignorieren.</p>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-d1cb7a3fc7bbece2", "to": "FIG-4a8d65dfd41de856", "fr": "R2.1.20", "tr": "R3.0.7", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li><strong>PCI (Protocol Control Information)</strong>: Gesamtlänge ändert sich von 2 Byte auf 5 Byte.\n</li><li><strong>LDL (4 Bit)</strong>: Entfällt bzw. wird ersetzt durch das Feld <code>Res (4 Bit)</code> (Reserved).\n</li><li><strong>DL (Data Length)</strong>: Feldbreite wird von 8 Bit auf 32 Bit vergrößert.\n</li></ul>"}]};
